async () => {
  const get = async u => (await (await fetch(u)).text());
  const rows = h => [...new DOMParser().parseFromString(h,'text/html').querySelectorAll('tbody#the-list tr')].map(r=>r.id+': '+(r.querySelector('.row-title')?.textContent));
  const counts = h => [...new DOMParser().parseFromString(h,'text/html').querySelectorAll('.subsubsub li')].map(l=>l.textContent.trim().replace(/\s+/g,' '));
  const pub = await get('/wp-admin/edit.php?post_status=publish&post_type=post');
  const tr = await get('/wp-admin/edit.php?post_status=trash&post_type=post');
  const home = await get('/');
  const p7 = await fetch('/?p=7'), p8 = await fetch('/?p=8');
  return {counts: counts(pub), published: rows(pub), trash: rows(tr), homeHas4: /Test post 4/.test(home), homeHas5: /Test post 5\b/.test(home), p7: p7.status, p8: p8.status};
}

